t.script:
document.addEventListener("DOMContentLoaded", function () {

    // =================================================
    // ELEMENTS HTML
    // =================================================

    const input =
        document.getElementById("plant-image");

    const fileName =
        document.getElementById("selected-file");

    const previewContainer =
        document.getElementById(
            "image-preview-container"
        );

    const preview =
        document.getElementById("image-preview");

    const analysisAction =
        document.getElementById("analysis-action");

    const startAnalysis =
        document.getElementById("start-analysis");


    // =================================================
    // IDENTIFIANT DU DIAGNOSTIC ODOO
    // =================================================

    let diagnosticId = null;


    // =================================================
    // VERIFICATION DE LA PAGE
    // =================================================

    if (!input) {
        return;
    }


    // =================================================
    // SELECTION DE L'IMAGE
    // =================================================

    input.addEventListener(
        "change",
        async function () {

            const file = input.files[0];


            // =================================================
            // AUCUNE IMAGE
            // =================================================

            if (!file) {

                fileName.textContent =
                    "Aucune image sélectionnée";

                previewContainer.style.display =
                    "none";

                analysisAction.style.display =
                    "none";

                preview.src = "";

                diagnosticId = null;

                return;
            }


            // =================================================
            // APERCU LOCAL DE L'IMAGE
            // =================================================

            fileName.textContent =
                "Image sélectionnée : " + file.name;


            const imageUrl =
                URL.createObjectURL(file);

            preview.src = imageUrl;

            previewContainer.style.display =
                "block";


            // =================================================
            // AFFICHAGE DU BOUTON D'ANALYSE
            // =================================================

            analysisAction.style.display =
                "block";


            // =================================================
            // PREPARATION DE L'ENVOI
            // =================================================

            const formData =
                new FormData();

            formData.append(
                "plant_image",
                file
            );


            // =================================================
            // ENVOI DE L'IMAGE VERS ODOO
            // =================================================

            try {

                const response =
                    await fetch(
                        "/diagnostic/upload",
                        {
                            method: "POST",
                            body: formData
                        }
                    );


                const result =
                    await response.json();


                console.log(
                    "Réponse Odoo :",
                    result
                );


                // =================================================
                // DIAGNOSTIC CREE
                // =================================================

                if (result.success) {

                    diagnosticId =
                        result.diagnostic_id;


                    fileName.textContent =
                        "Image envoyée : "
                        + result.filename;


                    console.log(
                        "Diagnostic ID :",
                        diagnosticId
                    );


                } else {

                    diagnosticId = null;

                    fileName.textContent =
                        result.message;

                }


            } catch (error) {

                console.error(
                    "Erreur lors de l'envoi de l'image :",
                    error
                );


                diagnosticId = null;

                fileName.textContent =
                    "Erreur lors de l'envoi de l'image";

            }

        }
    );


    // =================================================
    // LANCEMENT DE L'ANALYSE
    // =================================================

    if (startAnalysis) {

        startAnalysis.addEventListener(
            "click",
            async function () {


                // =================================================
                // VERIFICATION DU DIAGNOSTIC
                // =================================================

                if (!diagnosticId) {

                    console.error(
                        "Aucun diagnostic disponible"
                    );

                    fileName.textContent =
                        "Veuillez sélectionner une image";

                    return;
                }


                // =================================================
                // DESACTIVATION DU BOUTON
                // =================================================

                startAnalysis.disabled = true;

                startAnalysis.textContent =
                    "⏳ Analyse en cours...";


                // =================================================
                // PREPARATION DE LA REQUETE
                // =================================================

                const formData =
                    new FormData();

                formData.append(
                    "diagnostic_id",
                    diagnosticId
                );


                // =================================================
                // APPEL DE LA ROUTE ODOO
                // =================================================

                try {

                    const response =
                        await fetch(
                            "/diagnostic/start",
                            {
                                method: "POST",
                                body: formData
                            }
                        );


                    const result =
                        await response.json();


                    console.log(
                        "Réponse analyse :",
                        result
                    );


                    // =================================================
                    // ANALYSE LANCEE
                    // =================================================

                    if (result.success) {

                        fileName.textContent =
                            "🔎 " + result.state_label;


                        startAnalysis.textContent =
                            "🔎 En analyse";


                        console.log(
                            "État du diagnostic :",
                            result.state
                        );


                    } else {

                        fileName.textContent =
                            result.message;

                        startAnalysis.disabled =
                            false;

                        startAnalysis.textContent =
                            "🔎 Lancer l'analyse";

                    }


                } catch (error) {

                    console.error(
                        "Erreur lors du lancement de l'analyse :",
                        error
                    );


                    fileName.textContent =
                        "Erreur lors du lancement de l'analyse";


                    startAnalysis.disabled =
                        false;

                    startAnalysis.textContent =
                        "🔎 Lancer l'analyse";

                }

            }
        );

    }

});
